<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#182235;font-size:11px}h1{font-size:24px;margin:0}p{margin:5px 0;line-height:1.45}.head{display:flex;justify-content:space-between;border-bottom:2px solid #182235;padding-bottom:14px;margin-bottom:20px}.brand{font-size:20px;font-weight:700}.muted{color:#68758b;font-size:10px}.meta{width:100%;margin-bottom:20px}.meta td{vertical-align:top;padding-right:18px}.label{font-size:9px;color:#68758b;text-transform:uppercase;letter-spacing:1px}.items{width:100%;border-collapse:collapse}.items th{background:#f1f4f8;text-align:left;padding:8px;font-size:9px;text-transform:uppercase}.items td{border-bottom:1px solid #e3e7ee;padding:8px}.right{text-align:right}.totals{width:280px;margin-left:auto;margin-top:15px;border-collapse:collapse}.totals td{padding:6px}.grand td{font-size:15px;font-weight:700;border-top:2px solid #182235;padding-top:10px}.footer{border-top:1px solid #e3e7ee;margin-top:35px;padding-top:12px;text-align:center;color:#68758b;font-size:9px}</style></head><body><div class="head"><div><div class="brand">JALVAN</div><div class="muted">Custom Branded Water Bottles</div></div><div class="right"><h1>{{ $order->order_number }}</h1><div>{{ $order->order_date?->format('d M Y') }}</div></div></div><table class="meta"><tr><td><div class="label">Customer</div><strong>{{ $order->customer->business_name }}</strong><p>{{ $order->customer->customer_code }}<br>{{ $order->customer->user?->mobile }}<br>{{ $order->customer->user?->email }}</p></td><td><div class="label">Delivery</div><p>{{ $order->delivery_address ?: 'Same as customer address' }}<br>{{ collect([$order->delivery_city,$order->delivery_state,$order->delivery_pincode])->filter()->implode(', ') }}</p></td><td><div class="label">Status</div><strong>{{ ucwords(str_replace('_',' ',$order->status)) }}</strong><p>Required: {{ $order->required_date?->format('d M Y') ?: 'As scheduled' }}</p></td></tr></table><table class="items"><thead><tr><th>#</th><th>Product / Description</th><th>Qty</th><th class="right">Unit Price</th><th class="right">Discount</th><th class="right">Tax</th><th class="right">Total</th></tr></thead><tbody>@foreach($order->items as $i=>$item)<tr><td>{{ $i+1 }}</td><td><strong>{{ $item->product?->name ?: 'Custom item' }}</strong><br>{{ $item->description }}</td><td>{{ rtrim(rtrim(number_format($item->quantity,3,'.',''), '0'),'.') }} {{ $item->unit }}</td><td class="right">₹{{ number_format($item->unit_price,2) }}</td><td class="right">₹{{ number_format($item->discount_amount,2) }}</td><td class="right">₹{{ number_format($item->tax_amount,2) }}</td><td class="right"><strong>₹{{ number_format($item->line_total,2) }}</strong></td></tr>@endforeach</tbody></table><table class="totals"><tr><td>Subtotal</td><td class="right">₹{{ number_format($order->subtotal,2) }}</td></tr><tr><td>Discount</td><td class="right">− ₹{{ number_format($order->discount_amount,2) }}</td></tr><tr><td>Tax</td><td class="right">₹{{ number_format($order->tax_amount,2) }}</td></tr><tr><td>Shipping + Other</td><td class="right">₹{{ number_format($order->shipping_amount+$order->other_amount,2) }}</td></tr><tr class="grand"><td>Grand Total</td><td class="right">₹{{ number_format($order->grand_total,2) }}</td></tr></table><div style="margin-top:25px"><div class="label">Notes</div><p>{{ $order->notes ?: 'Thank you for your business.' }}</p></div><div class="footer">JALVAN · Custom Branded Water Bottles · Thank you for your business.</div></body></html>
